import React from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Building2, MapPin, Calendar, DollarSign, ChevronLeft, Send } from 'lucide-react';

const OpportunityDetail = () => {
  const navigate = useNavigate();
  // في المشروع الحقيقي، سنستخدم id لجلب البيانات من الـ API
  const { id } = useParams();

  const handleApply = () => {
    alert("Application sent successfully to the company!");
    navigate('/myapplication'); // انتقال تلقائي لصفحة التتبع بعد التقديم
  };

  return (
    <div style={{ padding: '40px 20px', maxWidth: '900px', margin: '0 auto', minHeight: '90vh' }}>
      {/* Back Button */}
      <button 
        onClick={() => navigate('/opportunities')}
        style={{ display: 'flex', alignItems: 'center', gap: '5px', border: 'none', background: 'none', color: '#6b7280', cursor: 'pointer', marginBottom: '20px' }}
      >
        <ChevronLeft size={20} /> Back to Opportunities
      </button>

      <div style={{ backgroundColor: 'white', borderRadius: '20px', boxShadow: '0 10px 30px rgba(0,0,0,0.08)', overflow: 'hidden' }}>
        {/* Header Section */}
        <div style={{ padding: '40px', borderBottom: '1px solid #f0f0f0', backgroundColor: '#faf9ff' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start' }}>
            <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
              <div style={{ backgroundColor: '#fff', padding: '15px', borderRadius: '15px', boxShadow: '0 4px 10px rgba(0,0,0,0.05)' }}>
                <Building2 size={40} color="#4a3f6b" />
              </div>
              <div>
                <h1 style={{ margin: 0, color: '#1f2937', fontSize: '24px' }}>Frontend Development Internship</h1>
                <p style={{ margin: '5px 0 0', color: '#6b7280', fontSize: '18px' }}>Tech Solutions Inc.</p>
              </div>
            </div>
            <button 
              onClick={handleApply}
              style={{ backgroundColor: '#4a3f6b', color: 'white', border: 'none', padding: '12px 25px', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '8px' }}
            >
              <Send size={18} /> Apply Now
            </button>
          </div>

          <div style={{ display: 'flex', gap: '20px', marginTop: '25px', flexWrap: 'wrap' }}>
            <span style={{ display: 'flex', alignItems: 'center', gap: '5px', color: '#666' }}><MapPin size={18} /> Constantine, Algeria</span>
            <span style={{ display: 'flex', alignItems: 'center', gap: '5px', color: '#666' }}><Calendar size={18} /> 3 Months</span>
            <span style={{ display: 'flex', alignItems: 'center', gap: '5px', color: '#666' }}><DollarSign size={18} /> Paid Internship</span>
          </div>
        </div>

        {/* Content Section */}
        <div style={{ padding: '40px' }}>
          <h3 style={{ color: '#4a3f6b', marginBottom: '15px' }}>About the Internship</h3>
          <p style={{ color: '#4b5563', lineHeight: '1.6', marginBottom: '30px' }}>
            We are looking for a passionate Frontend Developer intern to join our dynamic team. 
            You will work on building modern web interfaces using React.js and Tailwind CSS. 
            This is a great opportunity to gain hands-on experience in a professional environment.
          </p>

          <h3 style={{ color: '#4a3f6b', marginBottom: '15px' }}>Requirements</h3>
          <ul style={{ color: '#4b5563', lineHeight: '1.8', paddingLeft: '20px' }}>
            <li>Currently studying Computer Science or related field (L3 or Master).</li>
            <li>Basic knowledge of JavaScript (ES6+), HTML, and CSS.</li>
            <li>Familiarity with React.js is a plus.</li>
            <li>Good communication skills and eagerness to learn.</li>
          </ul>
          <h3 style={{ color: '#4a3f6b', marginTop: '30px', marginBottom: '15px' }}>Technical Tags</h3>
          <div style={{ display: 'flex', gap: '10px' }}>
            {['React', 'Tailwind CSS', 'JavaScript'].map(tag => (
              <span key={tag} style={{ backgroundColor: '#f3e8ff', color: '#7e22ce', padding: '6px 15px', borderRadius: '20px', fontSize: '14px', fontWeight: '500' }}>
                {tag}
              </span>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default OpportunityDetail;
